export async function savePost(title: string, content: string): Promise<Post> {
  const post = { id: randomUUID(), title, content, createdAt: new Date().toISOString() }
  await mkdir(directory, { recursive: true })
  await appendFile(file, JSON.stringify(post) + '\n', 'utf8')
