import { updateTag } from 'next/cache'
import { redirect } from 'next/navigation'
import { savePost } from './posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || !title.trim() || title.length > 200 ||
      typeof content !== 'string' || !content.trim() || content.length > 10000) {
    throw new Error('A title and content are required.')
  }

  await savePost(title.trim(), content.trim())
  // Unlike revalidateTag('posts', 'max'), this blocks the next read for fresh data.
  updateTag('posts')
  redirect('/')
}
"}

